const FIELDS={
  work:new Set(["WORK","ACTUAL_WORK","ACTUAL_REGULAR_WORK","ACTUAL_OVERTIME_WORK","REMAINING_WORK","REMAINING_REGULAR_WORK","REMAINING_OVERTIME_WORK","PLANNED_WORK","BUDGET_WORK"]),
