"""Native existing-plan identities and intended-versus-observed task corrections.

This module has no transport, workspace writer or provider mutation. It composes
the maintained typed source model, native CSDL, original reader identity joins,
and PssUpdateV1 plan/review format. Its inputs are complete retained observations.
"""
from __future__ import annotations

import copy
import datetime as dt
from decimal import Decimal, InvalidOperation

from .capture import PROJECT_COLLECTIONS, _native_guid, native_capture_identity
from .planner import (DEFAULT_TASK_FIELDS, FAMILIES, check_edition, convert,
                      metadata_from_probe, typed, verify_plan)
from .storage import checked_id
from .target import TargetError, digest, guid

MAPPED_FAMILIES = ("tasks", "resources", "assignments", "dependencies")
ENTITIES = {"tasks": "msdyn_projecttask", "resources": "msdyn_projectteam",
            "assignments": "msdyn_resourceassignment",
            "dependencies": "msdyn_projecttaskdependency"}
PROJECT_NAV = {"tasks": "msdyn_project", "resources": "msdyn_project",
               "assignments": "msdyn_projectid", "dependencies": "msdyn_Project"}
RULE_KEYS = {"target", "convert", "values", "timezone", "fold"}
DISPOSITIONS = {"retained_difference", "needs_correction", "manual_followup",
                "observed_resolved"}


def fail(code, message):
    raise TargetError(code, message)


def finding(code, message, *, family=None, keys=None, fields=None, evidence=None):
    value = {"code": code, "message": message, "family": family,
             "keys": list(keys or []), "fields": list(fields or []),
             "severity": "review", "evidence": evidence or {}}
    value["id"] = digest(value)
    return value


def same_value(left, right, rule=None):
    """Keep booleans distinct from numbers; normalize dates only by an UTC rule."""
    if isinstance(left, bool) or isinstance(right, bool):
        return type(left) is type(right) and left == right
    if left is None or right is None:
        return left is right
    if isinstance(left, (int, float, Decimal)) and isinstance(right, (int, float, Decimal)):
        try:
            a, b = Decimal(str(left)), Decimal(str(right))
            return a.is_finite() and b.is_finite() and a == b
        except InvalidOperation:
            return False
    if type(left) is type(right) and left == right:
        return True
    if (rule or {}).get("convert") == "utc" and isinstance(left, str) and isinstance(right, str):
        try:
            a = dt.datetime.fromisoformat(left.replace("Z", "+00:00"))
            b = dt.datetime.fromisoformat(right.replace("Z", "+00:00"))
            return a.tzinfo is not None and b.tzinfo is not None and a == b
        except ValueError:
            return False
    return False


def field_projection(edition, profile, metadata, mappings=None):
    """Convert selected original task fields without constructing creation payloads."""
    model = check_edition(edition)
    selected = copy.deepcopy({} if mappings is None else mappings)
    if not isinstance(selected, dict) or set(selected) - {"task_fields", "date_decisions", "retain_source_note"}:
        fail("COMMISSIONING_MAPPINGS", "Select task_fields, date_decisions and an optional retained-source note.")
    rules = selected.get("task_fields", copy.deepcopy(DEFAULT_TASK_FIELDS))
    if not isinstance(rules, dict) or "NAME" not in rules:
        fail("COMMISSIONING_TASK_FIELDS", "Keep an explicit NAME mapping and each selected field conversion.")
    dates = selected.get("date_decisions", {})
    task_keys = {row["key"] for row in model["tasks"]}
    if not isinstance(dates, dict) or set(dates) - task_keys:
        fail("COMMISSIONING_DATE_ROWS", "Date decisions must name tasks in the selected source edition.")
    for key, decisions in dates.items():
        if not isinstance(decisions, dict) or set(decisions) - set(rules):
            fail("COMMISSIONING_DATE_FIELDS", "Keep date decisions on explicitly mapped source fields.")
    forbidden = {metadata.entity("msdyn_projecttask")["key"].lower(), "statecode",
                 "msdyn_project", "msdyn_projectbucket", "msdyn_parenttask",
                 "msdyn_effort", "msdyn_effortcompleted", "msdyn_effortremaining"}
    projection, findings, mapped = [], [], set()
    for row in model["tasks"]:
        seen = set()
        for field, base in rules.items():
            if not isinstance(field, str) or not isinstance(base, dict) or set(base) - RULE_KEYS:
                fail("COMMISSIONING_FIELD_RULE", "Each source field needs one explicit native field and conversion.")
            rule = copy.deepcopy(base)
            decision = dates.get(row["key"], {}).get(field)
            if decision is not None:
                if not isinstance(decision, dict) or set(decision) - {"timezone", "fold"}:
                    fail("COMMISSIONING_DATE_DECISION", "A date decision may select time zone and fold only.")
                rule.update(decision)
            wanted = rule.get("target")
            if not isinstance(wanted, str) or not wanted:
                fail("COMMISSIONING_FIELD_RULE", "Select the actual native target field.")
            target_field = metadata.field("msdyn_projecttask", wanted)
            if target_field.lower() in forbidden or target_field.startswith("_"):
                fail("COMMISSIONING_MANAGED_FIELD", "Task corrections preserve native identities, hierarchy, buckets and calculated fields.")
            if target_field in seen:
                fail("COMMISSIONING_FIELD_COLLISION", "Two source fields select the same native task property.")
            seen.add(target_field)
            original = typed(row, field)
            if original is None:
                continue
            value = convert(original, rule, profile)
            projection.append({"family": "tasks", "key": row["key"],
                               "source_field": field, "source_value": copy.deepcopy(original),
                               "target_field": target_field, "target_value": value,
                               "conversion": rule})
            mapped.add((row["key"], field))
    # The complete source remains authoritative, including omitted collections and history.
    for family in FAMILIES:
        if family != "tasks" and model[family]:
            findings.append(finding("COMMISSIONING_RETAINED_" + family.upper(),
                "This task-correction route retains the complete original " + family +
                "; it does not create or automatically update that native family.",
                family=family, keys=[row["key"] for row in model[family]]))
    for row in model["tasks"]:
        retained = sorted(field for field in row.get("fields", {})
                          if (row["key"], field) not in mapped)
        if retained:
            findings.append(finding("COMMISSIONING_RETAINED_TASK_FIELDS",
                "These original task fields remain in the source and are outside this selected correction projection.",
                family="tasks", keys=[row["key"]], fields=retained))
    selected["task_fields"] = copy.deepcopy(rules)
    selected["date_decisions"] = copy.deepcopy(dates)
    return projection, findings, selected


def build_inventory(capture, project, project_receipt, teams, metadata, project_id,
                    *, transport_sha256, team_capture_sha256):
    """Keep complete project-scoped native rows and original reader candidates."""
    project_id = guid(project_id)
    project_key = metadata.entity("msdyn_project")["key"]
    if guid(project.get(project_key)) != project_id:
        fail("COMMISSIONING_PROJECT_ID", "The original native read returned another project.")
    model = check_edition(capture)
    families = {}
    for family in MAPPED_FAMILIES:
        entity = ENTITIES[family]
        key = metadata.entity(entity)["key"]
        project_column = metadata.lookup(entity, PROJECT_NAV[family])
        rows = teams if family == "resources" else project.get(PROJECT_COLLECTIONS[family])
        if not isinstance(rows, list):
            fail("COMMISSIONING_COLLECTION", "Retain the complete native " + family + " collection.")
        saved, seen = [], set()
        for row in rows:
            if not isinstance(row, dict):
                fail("COMMISSIONING_NATIVE_ROW", "A captured native row must be an object.")
            identity = guid(row.get(key))
            if identity in seen:
                fail("COMMISSIONING_DUPLICATE_NATIVE_ID", "The captured project repeats a native " + family + " GUID.")
            seen.add(identity)
            if project_column in row:
                if guid(row[project_column]) != project_id:
                    fail("COMMISSIONING_ROW_PROJECT", "A captured native row belongs to another project.")
                membership = {"kind": "native_lookup", "field": project_column, "project_id": project_id}
            elif family != "resources":
                membership = {"kind": "expanded_project_relationship",
                              "field": PROJECT_COLLECTIONS[family], "project_id": project_id}
            else:
                fail("COMMISSIONING_TEAM_PROJECT", "A selected project-team row lacks its actual project lookup.")
            candidates = [item["key"] for item in model.get(family, [])
                          if family != "resources" and _native_guid(item) == identity]
            saved.append({"native_guid": identity, "entity": entity,
                          "native_key": key, "native_sha256": digest(row),
                          "native": copy.deepcopy(row), "membership": membership,
                          "reader_candidates": candidates})
        families[family] = saved
    bucket_column = metadata.lookup("msdyn_projecttask", "msdyn_projectbucket")
    buckets = [{"task_id": row["native_guid"],
                "present": bucket_column in row["native"],
                "bucket_id": row["native"].get(bucket_column),
                "native_sha256": row["native_sha256"]}
               for row in families["tasks"]]
    result = {"schema": "portfolio.imported-plan-inventory.v1", "project_id": project_id,
              "capture_edition_id": capture["id"], "project": copy.deepcopy(project),
              "project_response_sha256": project_receipt["body_sha256"],
              "project_receipt": copy.deepcopy(project_receipt), "families": families,
              "bucket_observations": buckets, "single_bucket_selected": False,
              "read_transport_sha256": transport_sha256,
              "team_capture_sha256": team_capture_sha256,
              "observation_semantics": "complete sequential native reads; no atomic snapshot assertion"}
    result["sha256"] = digest(result)
    return result


def verify_inventory(inventory):
    body = copy.deepcopy(inventory)
    checksum = body.pop("sha256", None)
    if (body.get("schema") != "portfolio.imported-plan-inventory.v1" or
            checksum != digest(body)):
        fail("COMMISSIONING_INVENTORY_HASH", "The complete original target inventory changed.")
    return inventory


class CapturedProject:
    def __init__(self, inventory):
        self.inventory = verify_inventory(inventory)

    def project(self):
        return self.inventory["project"], self.inventory["project_receipt"]


def checked_mapping(edition, capture, inventory, metadata, row_ids):
    """Operator choices stay explicit; names and GUID candidates never auto-bind."""
    model = check_edition(edition)
    inventory = verify_inventory(inventory)
    if capture["id"] != inventory["capture_edition_id"]:
        fail("COMMISSIONING_CAPTURE_EDITION", "The identity choices name another native capture.")
    if not isinstance(row_ids, dict) or set(row_ids) - set(MAPPED_FAMILIES):
        fail("COMMISSIONING_IDENTITY_FAMILIES", "Map tasks, project-team resources, assignments and dependencies explicitly.")
    result, findings = {family: {} for family in FAMILIES}, []
    for family in MAPPED_FAMILIES:
        choices = row_ids.get(family, {})
        source_keys = {row["key"] for row in model[family]}
        native = {row["native_guid"]: row for row in inventory["families"][family]}
        if not isinstance(choices, dict) or set(choices) - source_keys:
            fail("COMMISSIONING_SOURCE_KEY", "A mapping names a row outside the pinned source edition.")
        used = set()
        for key, value in choices.items():
            selected = guid(value)
            if selected not in native:
                fail("COMMISSIONING_TARGET_KEY", "Select an actual native row from this project's complete captured inventory.")
            if selected in used:
                fail("COMMISSIONING_NONINJECTIVE_MAP", "Two source rows cannot silently share one selected native row.")
            used.add(selected)
            result[family][key] = selected
        missing = sorted(source_keys - set(choices))
        if missing:
            findings.append(finding("COMMISSIONING_UNMAPPED_" + family.upper(),
                "These original rows have no reviewed native identity. Their source bytes and history remain retained.",
                family=family, keys=missing))
    plan = {"project_id": inventory["project_id"], "row_ids": result}
    identity_map, native_findings, evidence = native_capture_identity(
        plan, capture, CapturedProject(inventory), metadata)
    for item in native_findings:
        findings.append(finding(item["code"], "The selected provider identity has no unique original-reader counterpart.",
            family=item.get("family"), keys=[item["source_key"]], evidence=item))
    # Record source relationship disagreement separately from a reviewed row identity.
    by_uid = {}
    for family in ("tasks", "resources"):
        values = {}
        for row in model[family]:
            if row.get("uid") is not None:
                values.setdefault(str(row["uid"]), []).append(row["key"])
        by_uid[family] = values
    def source_native(family, uid):
        keys = by_uid[family].get(str(uid), []) if uid is not None else []
        return result[family].get(keys[0]) if len(keys) == 1 else None
    for family in ("assignments", "dependencies"):
        native = {row["native_guid"]: row["native"] for row in inventory["families"][family]}
        for row in model[family]:
            selected_id = result[family].get(row["key"])
            if selected_id is None:
                continue
            observed = native[selected_id]
            if family == "assignments":
                checks = [
                    ("task", source_native("tasks", row.get("task_uid")),
                     observed.get(metadata.lookup("msdyn_resourceassignment", "msdyn_taskid"))),
                    ("project_team", source_native("resources", row.get("resource_uid")),
                     observed.get(metadata.lookup("msdyn_resourceassignment", "msdyn_projectteamid"))),
                ]
            else:
                checks = [
                    ("predecessor", source_native("tasks", row.get("predecessor_uid")),
                     observed.get("_msdyn_predecessortask_value")),
                    ("successor", source_native("tasks", row.get("successor_uid")),
                     observed.get("_msdyn_successortask_value")),
                ]
            for field, intended, actual in checks:
                try:
                    matches = intended is not None and guid(actual) == intended
                except TargetError:
                    matches = False
                if not matches:
                    findings.append(finding("COMMISSIONING_RELATIONSHIP_DIFFERENCE",
                        "The original source relationship and selected native row require an explicit retained or manual resolution.",
                        family=family, keys=[row["key"]], fields=[field],
                        evidence={"intended_native_id": intended, "observed_native_id": actual,
                                  "selected_native_id": selected_id}))
    evidence["source_edition_id"] = edition["id"]
    evidence["inventory_sha256"] = inventory["sha256"]
    evidence["row_ids"] = result
    evidence["sha256"] = digest(evidence)
    return result, identity_map, findings, evidence


def compare_projection(edition, inventory, row_ids, projection):
    """Original source, converted intent and observed native values remain separate."""
    inventory = verify_inventory(inventory)
    tasks = {row["native_guid"]: row for row in inventory["families"]["tasks"]}
    fields, counts = [], {"equal": 0, "different": 0, "unmapped": 0, "unobserved": 0}
    for item in projection:
        record_id = row_ids.get("tasks", {}).get(item["key"])
        row = tasks.get(record_id)
        present = row is not None and item["target_field"] in row["native"]
        observed = row["native"].get(item["target_field"]) if row else None
        status = ("unmapped" if row is None else "unobserved" if not present else
                  "equal" if same_value(observed, item["target_value"], item["conversion"]) else "different")
        value = {**copy.deepcopy(item), "native_guid": record_id, "status": status,
                 "observed_present": present, "observed_value": copy.deepcopy(observed),
                 "observed_native_sha256": row["native_sha256"] if row else None}
        value["id"] = digest(value)
        fields.append(value)
        counts[status] += 1
    body = {"schema": "portfolio.intended-observed-comparison.v1", "source_edition_id": edition["id"],
            "source_edition_sha256": edition["sha256"], "capture_edition_id": inventory["capture_edition_id"],
            "inventory_sha256": inventory["sha256"], "fields": fields, "counts": counts}
    body["sha256"] = digest(body)
    return body


def exception_review(original, decisions, known_evidence):
    if not isinstance(decisions, list):
        fail("COMMISSIONING_EXCEPTION_DECISIONS", "Review each retained original import-exception row.")
    selected = {}
    for decision in decisions:
        if (not isinstance(decision, dict) or set(decision) - {"exception_id", "disposition", "note", "evidence_sha256"} or
                decision.get("disposition") not in DISPOSITIONS or
                not isinstance(decision.get("note"), str) or not decision["note"].strip()):
            fail("COMMISSIONING_EXCEPTION_DECISION", "An exception decision needs its original ID, disposition and note.")
        identity = decision.get("exception_id")
        if identity in selected:
            fail("COMMISSIONING_EXCEPTION_DUPLICATE", "Keep one explicit decision per original exception.")
        refs = decision.get("evidence_sha256", [])
        if not isinstance(refs, list) or any(ref not in known_evidence for ref in refs):
            fail("COMMISSIONING_EXCEPTION_EVIDENCE", "Select original retained import or native-capture evidence.")
        if decision["disposition"] == "observed_resolved" and not refs:
            fail("COMMISSIONING_EXCEPTION_EVIDENCE", "An observed-resolution decision needs selected retained evidence.")
        selected[identity] = copy.deepcopy(decision)
    if set(selected) != {item["id"] for item in original}:
        fail("COMMISSIONING_EXCEPTION_COVERAGE", "Keep exactly one decision for every original exception.")
    return [{"original": copy.deepcopy(item), "decision": selected[item["id"]],
             "decision_kind": "authored_operator_review"} for item in original]


def check_following_source(edition, original):
    model, before = check_edition(edition), check_edition(original)
    for family in MAPPED_FAMILIES:
        if {r["key"] for r in model[family]} != {r["key"] for r in before[family]}:
            fail("COMMISSIONING_CORRECTION_IDENTITIES", "A task correction preserves all original row identities.")
    structural = {"tasks": ("parent_uid",), "assignments": ("task_uid", "resource_uid"),
                  "dependencies": ("predecessor_uid", "successor_uid", "type", "lag")}
    for family, fields in structural.items():
        previous = {r["key"]: r for r in before[family]}
        for row in model[family]:
            if any(row.get(key) != previous[row["key"]].get(key) for key in fields):
                fail("COMMISSIONING_CORRECTION_STRUCTURE",
                     "Keep hierarchy, assignment and dependency changes as separate reviewed work.")
    return model


def observed_correction_plan(edition, original_edition, profile, probe, deployment_id,
                             parent, original_plan, inventory, current_records,
                             *, mappings=None, selected_fields=None):
    """Prepare updates even when original and following source editions are equal."""
    original = verify_plan(original_plan)
    model = check_following_source(edition, original_edition)
    inventory = verify_inventory(inventory)
    checked_id(deployment_id)
    if parent.get("state") not in {"CAPTURED", "ACCEPTED"} or not parent.get("adoption_review_sha256"):
        fail("COMMISSIONING_REVIEW_REQUIRED", "Capture and review the existing plan before preparing a correction.")
    if original["target_identity"]["profile"] != probe["profile"]:
        fail("COMMISSIONING_CORRECTION_TARGET", "Keep the exact reviewed target; use explicit rebind for another principal.")
    if parent.get("commissioning_inventory_sha256") is None:
        fail("COMMISSIONING_CORRECTION_BASIS", "Select the complete retained native inventory.")
    selected = copy.deepcopy(original["mappings"])
    if mappings is not None:
        if not isinstance(mappings, dict) or set(mappings) - {"task_fields", "date_decisions", "retain_source_note"}:
            fail("COMMISSIONING_CORRECTION_MAPPINGS", "Corrections select task fields and explicit date conversions.")
        selected.update(copy.deepcopy(mappings))
    m = metadata_from_probe(probe)
    projection, findings, selected = field_projection(edition, profile, m, selected)
    identities = {(item["key"], item["target_field"]) for item in projection}
    if selected_fields is None:
        chosen = identities
    else:
        if not isinstance(selected_fields, list):
            fail("COMMISSIONING_CORRECTION_FIELDS", "Select source_key and target_field pairs.")
        chosen = set()
        for item in selected_fields:
            if not isinstance(item, dict) or set(item) != {"source_key", "target_field"}:
                fail("COMMISSIONING_CORRECTION_FIELDS", "Each correction choice names one original task and native field.")
            key = (item["source_key"], item["target_field"])
            if key not in identities or key in chosen:
                fail("COMMISSIONING_CORRECTION_FIELDS", "A selected native field is absent or repeated.")
            chosen.add(key)
    basis = compare_projection(edition, inventory, original["row_ids"], projection)
    basis_fields = {(item["key"], item["target_field"]): item for item in basis["fields"]}
    entity = m.entity("msdyn_projecttask")
    project_column = m.lookup("msdyn_projecttask", "msdyn_project")
    operations, before_rows, already_current, retained, per_task = [], [], [], [], {}
    for item in projection:
        key = (item["key"], item["target_field"])
        if key in chosen:
            per_task.setdefault(item["key"], []).append(item)
    for source_key, items in sorted(per_task.items()):
        record_id = original["row_ids"].get("tasks", {}).get(source_key)
        if record_id is None:
            retained.append({"source_key": source_key, "reason": "unmapped_source_task"})
            continue
        record_id = guid(record_id)
        current = current_records.get(record_id)
        if (not isinstance(current, dict) or guid(current.get(entity["key"])) != record_id or
                guid(current.get(project_column)) != original["project_id"]):
            fail("COMMISSIONING_CORRECTION_NATIVE_ROW", "The selected current task is absent or outside the original project.")
        current_sha = digest(current)
        before_rows.append({"entity": "msdyn_projecttask", "record_id": record_id,
                            "source_key": source_key, "sha256": current_sha,
                            "native": copy.deepcopy(current)})
        before, values, conversions, comparisons = {}, {}, {}, []
        for item in items:
            field = item["target_field"]
            comparisons.append({**copy.deepcopy(basis_fields[(source_key, field)]),
                                "prepare_observed_present": field in current,
                                "prepare_observed_value": copy.deepcopy(current.get(field)),
                                "prepare_native_sha256": current_sha})
            if field not in current:
                retained.append({"source_key": source_key, "field": field,
                                 "reason": "native_property_not_observed", "native_sha256": current_sha})
                continue
            if same_value(current[field], item["target_value"], item["conversion"]):
                already_current.append({"source_key": source_key, "record_id": record_id,
                                        "field": field, "value": copy.deepcopy(current[field]),
                                        "native_sha256": current_sha})
            else:
                before[field], values[field] = copy.deepcopy(current[field]), copy.deepcopy(item["target_value"])
                conversions[field] = copy.deepcopy(item["conversion"])
        if not values:
            continue
        payload = {"@odata.type": entity["type"], entity["key"]: record_id, **values}
        m.validate_entity(payload)
        operation = {"action": "msdyn_PssUpdateV1", "entity": "msdyn_projecttask",
                     "record_id": record_id, "source_family": "tasks", "source_key": source_key,
                     "payload": payload, "intended_observed": comparisons,
                     "precondition": {"entity": "msdyn_projecttask", "record_id": record_id,
                         "project_id": original["project_id"], "before": before,
                         "observed_sha256": current_sha, "etag": current.get("@odata.etag"),
                         "comparison": "commissioned_typed", "conversions": conversions}}
        operation["id"] = digest(operation)
        operations.append(operation)
    if retained:
        findings.append(finding("COMMISSIONING_UNAUTOMATED_DIFFERENCES",
            "Unmapped tasks and absent native properties remain retained review items; no native value was invented.",
            family="tasks", evidence={"items": retained}))
    for code, text in (
        ("COMMISSIONING_EXISTING_TASK_CORRECTION",
         "Only listed fields on the selected existing tasks will be updated. No project, bucket, resource or task is created."),
        ("COMMISSIONING_OBSERVED_VALUE_BASIS",
         "Fields are selected by intended versus observed native values, including unchanged source intent. Complete source and original capture remain separate."),
        ("COMMISSIONING_BEFORE_VALUE_REVIEW",
         "Native before values are checked before queueing and execution. The scheduling action has no atomic conditional ETag parameter."),
        ("NATIVE_TRANSACTION_BOUNDARIES",
         "Each listed OperationSet is a separate transaction; earlier completed sets remain if a later set fails."),
    ):
        findings.append(finding(code, text, family="tasks"))
    size = profile.get("operation_set_size", 200)
    if isinstance(size, bool) or not isinstance(size, int) or not 1 <= size <= 200:
        fail("COMMISSIONING_SET_SIZE", "Select a native OperationSet size from 1 through 200.")
    batches = []
    for start in range(0, len(operations), size):
        chosen_ops = operations[start:start + size]
        number = len(batches) + 1
        batches.append({"number": number, "description": "portfolio:" + deployment_id + ":" + str(number),
                        "operations": chosen_ops, "sha256": digest(chosen_ops)})
    result = copy.deepcopy(original)
    result.update({"deployment_id": deployment_id, "source_edition_id": edition["id"],
        "source_edition_sha256": edition["sha256"], "source_ids": edition.get("source_ids", []),
        "probe_sha256": probe["sha256"], "mode": "task_correction", "origin": "external_import",
        "parent_deployment_id": parent["id"], "parent_revision": parent["revision"],
        "parent_plan_sha256": parent["plan_sha256"],
        "parent_comparison_sha256": parent["comparison_sha256"],
        "parent_inventory_sha256": parent["commissioning_inventory_sha256"],
        "adoption_review_sha256": parent["adoption_review_sha256"],
        "existing_project": True, "bucket_id": None, "immediate": [], "team_selections": [],
        "projection": projection, "mappings": selected, "batches": batches, "findings": findings,
        "correction_basis": basis, "native_before": before_rows, "already_current": already_current,
        "retained_corrections": retained,
        "selected_fields": [{"source_key": a, "target_field": b} for a, b in sorted(chosen)],
        "counts": {"source": {family: len(model[family]) for family in FAMILIES},
                   "immediate_actions": 0, "queued_operations": len(operations),
                   "operation_sets": len(batches), "already_current_fields": len(already_current)}})
    result.pop("sha256", None)
    result["sha256"] = digest(result)
    return verify_plan(result)


def verify_observed_before(operation, target):
    """Exact typed precondition for this additive plan; the original plans keep theirs."""
    condition = operation["precondition"]
    row = target.record(condition["entity"], condition["record_id"])
    m = target.metadata
    if (not isinstance(row, dict) or
            guid(row.get(m.entity(condition["entity"])["key"])) != condition["record_id"] or
            guid(row.get(m.lookup(condition["entity"], "msdyn_project"))) != condition["project_id"]):
        fail("TARGET_PRECONDITION", "The original commissioned task is absent or moved to another project.")
    changed = [field for field, value in condition["before"].items()
               if field not in row or not same_value(row[field], value, condition["conversions"].get(field))]
    if changed:
        fail("TARGET_PRECONDITION", "Native values changed after review: " + ", ".join(changed) +
             ". Keep the original set unexecuted and prepare a newly reviewed correction.")
    return {"entity": condition["entity"], "record_id": condition["record_id"],
            "current": row, "sha256": digest(row), "comparison": "commissioned_typed"}

"""Compile an immutable native target plan from the original MPXJ edition.

Original typed fields and every unmapped value remain in the source edition.
Only documented scheduling actions are emitted; target entity/field names come
from the selected environment's retained native CSDL.
"""
from __future__ import annotations

import datetime as dt
from decimal import Decimal, InvalidOperation
import math
import re
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError
import uuid

from .target import Metadata, TargetError, canonical, digest, guid, public_profile

FAMILIES = ("tasks", "resources", "assignments", "dependencies", "calendars")
DEFAULT_TASK_FIELDS = {
    "NAME": {"target": "msdyn_subject", "convert": "text"},
    "START": {"target": "msdyn_scheduledstart", "convert": "utc"},
    "FINISH": {"target": "msdyn_scheduledend", "convert": "utc"},
}
UNSUPPORTED_PROJECT_WRITES = {x.lower() for x in (
    "statecode", "msdyn_bulkgenerationstatus", "msdyn_globalrevisiontoken",
    "msdyn_calendarid", "msdyn_effort", "msdyn_effortcompleted",
    "msdyn_effortremaining", "msdyn_progress", "msdyn_finish",
    "msdyn_taskearlieststart", "msdyn_duration",
)}
IDENTITY_FIELDS = {
    "UNIQUE_ID", "GUID", "ID", "PARENT_TASK_UNIQUE_ID", "TASK_UNIQUE_ID",
    "RESOURCE_UNIQUE_ID", "OUTLINE_LEVEL", "OUTLINE_NUMBER",
}


def typed(row, field, default=None):
    value = row.get("fields", {}).get(field)
    return value if value is not None else default


def scalar(value, default=None):
    if value is None:
        return default
    if not isinstance(value, dict) or "type" not in value or "value" not in value:
        raise TargetError("SOURCE_TYPED_VALUE", "Use the original typed MPXJ field value.")
    return value["value"]


def text_value(row, field="NAME", default=""):
    value = scalar(typed(row, field), default)
    if value is None:
        return default
    return str(value)


def field_error(family, row, field, message):
    raise TargetError("TARGET_FIELD_CONVERSION", family + "/" + row["key"] + "/" + field + ": " + message)


def metadata_from_probe(probe):
    check = dict(probe)
    expected = check.pop("sha256", None)
    if expected != digest(check) or probe.get("schema") != "portfolio.target-probe.v1":
        raise TargetError("TARGET_PROBE_DIGEST", "The original native target probe changed.")
    selected = probe["metadata"]
    if selected.get("schema") != "portfolio.native-target-metadata.v1":
        raise TargetError("TARGET_METADATA", "Use the selected original native CSDL projection.")
    value = Metadata.__new__(Metadata)
    value.sha256 = selected["sha256"]
    value.entities, value.actions = selected["entities"], selected["actions"]
    return value


def local_to_utc(value, timezone, fold=None):
    if not isinstance(value, str):
        raise TargetError("SOURCE_DATE", "The original date must be a string.")
    try:
        parsed = dt.datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise TargetError("SOURCE_DATE", "The original local date is invalid.") from exc
    if parsed.tzinfo is not None:
        return parsed.astimezone(dt.timezone.utc).isoformat().replace("+00:00", "Z")
    if not timezone:
        raise TargetError("SOURCE_TIMEZONE", "Choose the source project time zone for local dates.")
    try:
        zone = ZoneInfo(timezone)
    except ZoneInfoNotFoundError as exc:
        raise TargetError("SOURCE_TIMEZONE", "The selected IANA time zone is unavailable.") from exc
    candidates = []
    for candidate_fold in (0, 1):
        candidate = parsed.replace(tzinfo=zone, fold=candidate_fold)
        if candidate.astimezone(dt.timezone.utc).astimezone(zone).replace(tzinfo=None) == parsed:
            if not any(old.utcoffset() == candidate.utcoffset() for old in candidates):
                candidates.append(candidate)
    if not candidates:
        raise TargetError("SOURCE_NONEXISTENT_TIME", "The local date falls in a daylight-saving gap.")
    if len(candidates) > 1:
        if fold not in (0, 1):
            raise TargetError("SOURCE_AMBIGUOUS_TIME", "Choose fold 0 or 1 for this repeated local time.")
        chosen = next(x for x in candidates if x.fold == fold)
    else:
        chosen = candidates[0]
    return chosen.astimezone(dt.timezone.utc).isoformat().replace("+00:00", "Z")


def convert(value, rule, profile):
    if value is None or scalar(value) is None:
        return None
    kind, raw = value["type"], value["value"]
    conversion = rule.get("convert", "text")
    if conversion == "text":
        if kind not in ("string", "enum", "integer", "number", "boolean"):
            raise TargetError("TARGET_CONVERSION", "Choose an explicit conversion for " + kind + ".")
        return str(raw)
    if conversion == "boolean":
        if kind != "boolean" or not isinstance(raw, bool):
            raise TargetError("TARGET_CONVERSION", "Expected an original boolean.")
        return raw
    if conversion == "utc":
        if kind not in ("local_datetime", "local_date", "string"):
            raise TargetError("TARGET_CONVERSION", "Expected an original local date/time.")
        return local_to_utc(raw, rule.get("timezone", profile.get("source_timezone")), rule.get("fold"))
    if conversion in ("integer", "number", "percent_fraction"):
        try:
            number = Decimal(str(raw))
        except InvalidOperation as exc:
            raise TargetError("TARGET_CONVERSION", "Expected a finite original number.") from exc
        if not number.is_finite():
            raise TargetError("TARGET_CONVERSION", "Expected a finite original number.")
        if conversion == "integer":
            if number != number.to_integral_value():
                raise TargetError("TARGET_CONVERSION", "A fractional value cannot become a native integer.")
            return int(number)
        if conversion == "percent_fraction":
            if not Decimal(0) <= number <= Decimal(100):
                raise TargetError("TARGET_CONVERSION", "A percentage must be between 0 and 100.")
            number /= Decimal(100)
        converted = float(number)
        if not math.isfinite(converted) or Decimal(str(converted)) != number:
            raise TargetError("TARGET_NUMBER_PRECISION",
                              "This number cannot be represented exactly by the selected JSON numeric conversion.")
        return converted
    if conversion == "choice":
        key = str(raw)
        choices = rule.get("values", {})
        if key not in choices or not isinstance(choices[key], int) or isinstance(choices[key], bool):
            raise TargetError("TARGET_CHOICE", "Choose the native option value for " + key + ".")
        return choices[key]
    raise TargetError("TARGET_CONVERSION", "Unknown explicit conversion " + str(conversion))


def check_edition(edition):
    if not isinstance(edition, dict) or not re.fullmatch(r"[0-9a-f]{64}", str(edition.get("id", ""))):
        raise TargetError("SOURCE_EDITION", "Choose a complete immutable PortfolioWorkspace edition.")
    model = edition.get("model", {})
    if model.get("schema") != "project-portfolio-model.v1":
        raise TargetError("SOURCE_MODEL", "Expected the original project-portfolio-model.v1.")
    for family in FAMILIES:
        rows = model.get(family)
        if not isinstance(rows, list):
            raise TargetError("SOURCE_FAMILY", "The original " + family + " family must be an array.")
        keys = [row.get("key") for row in rows]
        if any(not isinstance(key, str) or not key for key in keys) or len(set(keys)) != len(keys):
            raise TargetError("SOURCE_KEYS", "Original row keys must be present and unique.")
    return model


def native_id(deployment_id, family, key):
    return str(uuid.uuid5(uuid.NAMESPACE_URL, "portfolio-target:" + deployment_id + ":" + family + ":" + key))


def target_identity(profile, probe):
    return {"profile": public_profile(profile), "user_id": guid(probe["identity"]["UserId"]),
            "organization_id": guid(probe["identity"]["OrganizationId"]),
            "metadata_sha256": probe["metadata"]["sha256"]}


def prepare_schedule(edition, profile, probe, deployment_id, mappings=None):
    model = check_edition(edition)
    if not re.fullmatch(r"[0-9a-f]{64}", deployment_id):
        raise TargetError("DEPLOYMENT_ID", "Use the retained full deployment ID.")
    m = metadata_from_probe(probe)
    if probe["profile"] != public_profile(profile):
        raise TargetError("TARGET_PROFILE_CHANGED", "Probe and selected target profile differ.")
    mappings = mappings or {}
    if not isinstance(mappings, dict):
        raise TargetError("TARGET_MAPPINGS", "Mappings must be an object.")
    expected_mapping_keys = {
        "project_name", "project_id", "existing_project", "task_fields",
        "resource_names", "resource_team_members", "dependency_types",
        "date_decisions", "retain_source_note", "assignment_names",
    }
    if set(mappings) - expected_mapping_keys:
        raise TargetError("TARGET_MAPPINGS", "Unknown target mapping option: " + ", ".join(sorted(set(mappings) - expected_mapping_keys)))
    project = model.get("project", {})
    project_name = mappings.get("project_name") or text_value(project) or "Retained project"
    if not isinstance(project_name, str) or not project_name.strip():
        raise TargetError("TARGET_PROJECT_NAME", "A target project name is required.")
    existing_project = mappings.get("existing_project", False)
    if not isinstance(existing_project, bool):
        raise TargetError("TARGET_PROJECT_MODE", "Select create or append to an existing project.")
    if existing_project and not mappings.get("project_id"):
        raise TargetError("TARGET_PROJECT_SELECTION", "Select the exact existing native project ID.")
    project_id = guid(mappings["project_id"]) if mappings.get("project_id") else native_id(deployment_id, "project", "project")
    bucket_id = native_id(deployment_id, "bucket", "migration")
    row_ids = {family: {row["key"]: native_id(deployment_id, family, row["key"])
                        for row in model[family]} for family in FAMILIES}
    findings, projection, operations, immediate, used = [], [], [], [], set()

    def finding(code, message, *, family=None, keys=None, fields=None, severity="review"):
        body = {"code": code, "message": message, "family": family,
                "keys": keys or [], "fields": fields or [], "severity": severity}
        body["id"] = digest(body)
        findings.append(body)

    def entity(name, record_id, fields=None, links=None):
        schema = m.entity(name)
        payload = {"@odata.type": schema["type"], schema["key"]: guid(record_id)}
        for key, value in (fields or {}).items():
            payload[m.field(name, key)] = value
        for key, (other, other_id) in (links or {}).items():
            payload[m.field(name, key, navigation=True) + "@odata.bind"] = m.binding(other, other_id)
        m.validate_entity(payload)
        return payload

    def operation(action, payload, family, key):
        entity_name = payload["@odata.type"].removeprefix("Microsoft.Dynamics.CRM.")
        record_id = payload[m.entity(entity_name)["key"]]
        item = {"action": action, "entity": entity_name, "record_id": record_id,
                "source_family": family, "source_key": key, "payload": payload}
        item["id"] = digest(item)
        return item

    project_payload = entity("msdyn_project", project_id, {"msdyn_subject": project_name})
    if not existing_project:
        immediate.append({"id": digest({"create_project": project_payload}),
                          "action": "msdyn_CreateProjectV1", "parameters": {"Project": project_payload},
                          "entity": "msdyn_project", "record_id": project_id, "source_key": project.get("key", "project")})
    else:
        finding("EXISTING_PROJECT_APPEND",
                "This migration appends newly identified rows to the selected existing project; its current content remains.",
                keys=[project_id])
    used.add(("project", project.get("key", "project"), "NAME"))
    operations.append(operation("msdyn_PssCreateV1", entity("msdyn_projectbucket", bucket_id,
        {"msdyn_name": "Migration " + deployment_id[:12]},
        {"msdyn_project": ("msdyn_project", project_id)}), "project", "migration-bucket"))

    lookup = {}
    for family in FAMILIES:
        index = {}
        for row in model[family]:
            if row.get("uid") is not None:
                index.setdefault(str(row["uid"]), []).append(row)
        lookup[family] = index

    def resolve(family, source_uid, row, field):
        candidates = lookup[family].get(str(source_uid), []) if source_uid is not None else []
        if len(candidates) != 1:
            field_error(family, row, field, "The source UID does not identify exactly one retained row.")
        return candidates[0]

    team_map = mappings.get("resource_team_members", {})
    resource_names = mappings.get("resource_names", {})
    if not isinstance(team_map, dict) or not isinstance(resource_names, dict):
        raise TargetError("TARGET_RESOURCES", "Resource selections must be keyed by the original source row key.")
    if set(team_map) - set(row_ids["resources"]) or set(resource_names) - set(row_ids["resources"]):
        raise TargetError("TARGET_RESOURCES", "A resource mapping names an absent source row.")
    team_selections = []
    for row in model["resources"]:
        key = row["key"]
        if key in team_map:
            team_id = guid(team_map[key])
            row_ids["resources"][key] = team_id
            team_selections.append({"source_key": key, "team_member_id": team_id, "existing": True})
        else:
            team_id = row_ids["resources"][key]
            name = resource_names.get(key) or text_value(row) or key
            payload = entity("msdyn_projectteam", team_id, {"msdyn_name": name},
                             {"msdyn_project": ("msdyn_project", project_id)})
            immediate.append({"id": digest({"create_team_member": payload}),
                              "action": "msdyn_CreateTeamMemberV1", "parameters": {"TeamMember": payload},
                              "entity": "msdyn_projectteam", "record_id": team_id, "source_key": key})
            team_selections.append({"source_key": key, "team_member_id": team_id, "existing": False})
        used.add(("resources", key, "NAME"))
    if model["resources"]:
        finding("RESOURCE_TEAM_MAPPING",
                "Source resources map to the selected native project team members; rates, calendars and cost history remain in the original source.",
                family="resources", keys=[r["key"] for r in model["resources"]])

    rules = mappings.get("task_fields", DEFAULT_TASK_FIELDS)
    if not isinstance(rules, dict) or "NAME" not in rules:
        raise TargetError("TARGET_TASK_RULES", "Task field mappings must include NAME.")
    date_decisions = mappings.get("date_decisions", {})
    parents, tasks = {}, {row["key"]: row for row in model["tasks"]}
    for row in model["tasks"]:
        parent_uid = row.get("parent_uid")
        parents[row["key"]] = resolve("tasks", parent_uid, row, "parent_uid")["key"] if parent_uid is not None else None
        if parents[row["key"]] == row["key"]:
            field_error("tasks", row, "parent_uid", "A task cannot be its own parent.")
    ordered, visiting, visited = [], set(), set()
    def visit(key):
        if key in visiting:
            raise TargetError("SOURCE_TASK_CYCLE", "The retained task hierarchy contains a cycle.")
        if key in visited:
            return
        visiting.add(key)
        if parents[key] is not None:
            visit(parents[key])
        visiting.remove(key)
        visited.add(key)
        ordered.append(tasks[key])
    for key in tasks:
        visit(key)

    for row in ordered:
        key, values = row["key"], {}
        for field, base_rule in rules.items():
            if not isinstance(base_rule, dict) or set(base_rule) - {"target", "convert", "values", "timezone", "fold"}:
                raise TargetError("TARGET_FIELD_RULE", "Each field needs one explicit target and conversion.")
            rule = dict(base_rule)
            per_row = date_decisions.get(key, {}).get(field)
            if per_row is not None:
                if not isinstance(per_row, dict) or set(per_row) - {"timezone", "fold"}:
                    raise TargetError("TARGET_DATE_DECISION", "Date decisions may select time zone and fold only.")
                rule.update(per_row)
            target_field = m.field("msdyn_projecttask", rule.get("target", ""))
            if target_field.lower() in {
                m.entity("msdyn_projecttask")["key"].lower(), "statecode",
                "msdyn_project", "msdyn_projectbucket", "msdyn_parenttask",
                "msdyn_effort", "msdyn_effortcompleted", "msdyn_effortremaining",
            } or target_field.startswith("_"):
                raise TargetError("TARGET_MANAGED_FIELD", "This native identity or calculated field is managed by the migration.")
            original = typed(row, field)
            if original is None:
                continue
            try:
                converted = convert(original, rule, profile)
            except TargetError as exc:
                field_error("tasks", row, field, str(exc))
            if target_field in values:
                raise TargetError("TARGET_FIELD_COLLISION", "Two source fields map to " + target_field + ".")
            values[target_field] = converted
            used.add(("tasks", key, field))
            projection.append({"family": "tasks", "key": key, "source_field": field,
                               "source_value": original, "target_field": target_field, "target_value": converted,
                               "conversion": rule})
        subject = m.field("msdyn_projecttask", "msdyn_subject")
        if not values.get(subject):
            values[subject] = key
        links = {"msdyn_project": ("msdyn_project", project_id),
                 "msdyn_projectbucket": ("msdyn_projectbucket", bucket_id)}
        if parents[key]:
            links["msdyn_parenttask"] = ("msdyn_projecttask", row_ids["tasks"][parents[key]])
        payload = entity("msdyn_projecttask", row_ids["tasks"][key], values, links)
        operations.append(operation("msdyn_PssCreateV1", payload, "tasks", key))

    assignment_names = mappings.get("assignment_names", {})
    if not isinstance(assignment_names, dict) or set(assignment_names) - set(row_ids["assignments"]):
        raise TargetError("TARGET_ASSIGNMENT_NAMES", "Assignment names must use existing source row keys.")
    for row in model["assignments"]:
        task = resolve("tasks", row.get("task_uid"), row, "task_uid")
        resource = resolve("resources", row.get("resource_uid"), row, "resource_uid")
        payload = entity("msdyn_resourceassignment", row_ids["assignments"][row["key"]],
            {"msdyn_name": assignment_names.get(row["key"]) or text_value(row) or row["key"]},
            {"msdyn_projectid": ("msdyn_project", project_id),
             "msdyn_taskid": ("msdyn_projecttask", row_ids["tasks"][task["key"]]),
             "msdyn_projectteamid": ("msdyn_projectteam", row_ids["resources"][resource["key"]])})
        operations.append(operation("msdyn_PssCreateV1", payload, "assignments", row["key"]))
        used.add(("assignments", row["key"], "NAME"))
    if model["assignments"]:
        finding("ASSIGNMENT_CONTOURS_RETAINED",
                "The native assignment links are created; original work contours, actual work and cost history remain in the source edition for reviewed later scheduling.",
                family="assignments", keys=[r["key"] for r in model["assignments"]])

    dependency_types = mappings.get("dependency_types", {})
    if not isinstance(dependency_types, dict):
        raise TargetError("TARGET_DEPENDENCY_TYPES", "Use an explicit native link-type mapping.")
    for row in model["dependencies"]:
        predecessor = resolve("tasks", row.get("predecessor_uid"), row, "predecessor_uid")
        successor = resolve("tasks", row.get("successor_uid"), row, "successor_uid")
        relation = row.get("type")
        if isinstance(relation, dict):
            relation = scalar(relation)
        relation = str(relation)
        target_type = dependency_types.get(relation)
        if not isinstance(target_type, int) or isinstance(target_type, bool):
            field_error("dependencies", row, "type", "Select the native link-type option for " + relation + ".")
        if target_type not in {item["Value"] for item in probe["link_type_choices"]}:
            field_error("dependencies", row, "type", "The selected option is absent from the native target metadata.")
        payload = entity("msdyn_projecttaskdependency", row_ids["dependencies"][row["key"]],
            {"msdyn_linktype": target_type},
            {"msdyn_project": ("msdyn_project", project_id),
             "msdyn_predecessortask": ("msdyn_projecttask", row_ids["tasks"][predecessor["key"]]),
             "msdyn_successortask": ("msdyn_projecttask", row_ids["tasks"][successor["key"]])})
        operations.append(operation("msdyn_PssCreateV1", payload, "dependencies", row["key"]))
        lag = row.get("lag")
        raw_lag = scalar(lag) if isinstance(lag, dict) else lag
        if raw_lag not in (None, 0, "0", "0.0"):
            finding("DEPENDENCY_LAG_RETAINED",
                    "This native link is created without importing the original nonzero lag; the exact lag remains in the source.",
                    family="dependencies", keys=[row["key"]], fields=["lag"])
    if model["calendars"]:
        finding("CALENDARS_RETAINED",
                "Original calendars, exceptions and working-time rules remain in the native source export; this target plan uses the selected environment's calendar.",
                family="calendars", keys=[r["key"] for r in model["calendars"]])
    omissions = {}
    source_rows = [("project", project)] + [(family, row) for family in FAMILIES for row in model[family]]
    for family, row in source_rows:
        for field, value in row.get("fields", {}).items():
            if (family, row["key"], field) in used or field in IDENTITY_FIELDS or scalar(value) is None:
                continue
            omissions.setdefault(family, {}).setdefault(field, []).append(row["key"])
    for family, fields in omissions.items():
        finding("SOURCE_FIELDS_RETAINED",
                "These original field values are preserved in the source edition and excluded from this native target write.",
                family=family, fields=[{"field": field, "keys": keys, "count": len(keys)}
                                       for field, keys in sorted(fields.items())])
    set_size = profile.get("operation_set_size", 200)
    batches = []
    for index in range(0, len(operations), set_size):
        selected = operations[index:index + set_size]
        number = len(batches) + 1
        batches.append({"number": number, "description": "portfolio:" + deployment_id + ":" + str(number),
                        "operations": selected, "sha256": digest(selected)})
    finding("NATIVE_TRANSACTION_BOUNDARIES",
            "Project/team creation is immediate. Each listed OperationSet is a separate native transaction; completed sets survive a later set's failure.",
            keys=[str(batch["number"]) for batch in batches])
    result = {
        "schema": "portfolio.target-plan.v1", "deployment_id": deployment_id,
        "source_edition_id": edition["id"], "source_edition_sha256": edition["sha256"],
        "source_ids": edition.get("source_ids", []), "target_identity": target_identity(profile, probe),
        "probe_sha256": probe["sha256"], "project_id": project_id, "project_name": project_name,
        "existing_project": existing_project, "bucket_id": bucket_id, "row_ids": row_ids,
        "team_selections": team_selections, "mappings": mappings, "projection": projection,
        "immediate": immediate, "batches": batches, "findings": findings,
        "counts": {"source": {family: len(model[family]) for family in FAMILIES},
                   "immediate_actions": len(immediate), "queued_operations": len(operations),
                   "operation_sets": len(batches)},
    }
    result["sha256"] = digest(result)
    return result


def verify_plan(plan):
    if not isinstance(plan, dict) or plan.get("schema") != "portfolio.target-plan.v1":
        raise TargetError("TARGET_PLAN", "Use an original immutable target plan.")
    content = dict(plan)
    expected = content.pop("sha256", None)
    if expected != digest(content):
        raise TargetError("TARGET_PLAN_CHANGED", "The reviewed native target plan changed.")
    seen_batches = set()
    for batch in plan.get("batches", []):
        if batch["number"] in seen_batches or batch["sha256"] != digest(batch["operations"]):
            raise TargetError("TARGET_BATCH_ID", "The original native batch identity changed.")
        seen_batches.add(batch["number"])
        identities = [(item["entity"], guid(item["record_id"])) for item in batch["operations"]]
        if len(identities) != len(set(identities)):
            raise TargetError("TARGET_ROW_CALL_UNIQUENESS",
                              "One native set must contain only one selected row call for an entity and record.")
        if len(batch["operations"]) > 200:
            raise TargetError("OPERATION_SET_LIMIT", "A native OperationSet holds at most 200 operations.")
    return plan


def review_schedule(plan, *, reviewer, note, accepted_findings):
    verify_plan(plan)
    required = {item["id"] for item in plan["findings"] if item["severity"] == "review"}
    accepted = set(accepted_findings)
    if accepted != required or any(x["severity"] == "error" for x in plan["findings"]):
        raise TargetError("TARGET_REVIEW", "Review every listed retained-source decision for this exact plan.")
    if not isinstance(reviewer, str) or not reviewer.strip() or not isinstance(note, str) or not note.strip():
        raise TargetError("TARGET_REVIEWER", "Record the operator and the target acceptance note.")
    result = {"schema": "portfolio.target-review.v1", "plan_sha256": plan["sha256"],
              "source_edition_id": plan["source_edition_id"], "deployment_id": plan["deployment_id"],
              "reviewer": reviewer.strip(), "note": note.strip(),
              "accepted_findings": sorted(accepted)}
    result["sha256"] = digest(result)
    return result

"""Private immutable source objects and original operation indexes for the target desk."""
from __future__ import annotations

from contextlib import contextmanager
import hashlib
import json
import os
from pathlib import Path
import re
import threading
import time
import uuid

from .target import TargetError, canonical, digest, utcnow

IDENTITY = re.compile(r"^[0-9a-f]{64}$")
_LOCAL_LOCKS = {}
_LOCAL_GUARD = threading.Lock()


def checked_id(value):
    if not isinstance(value, str) or not IDENTITY.fullmatch(value):
        raise TargetError("OPERATOR_ID", "Select the complete saved 64-character identity.")
    return value


@contextmanager
def file_lock(path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    key = str(path.resolve())
    with _LOCAL_GUARD:
        local = _LOCAL_LOCKS.setdefault(key, threading.RLock())
    with local:
        descriptor = os.open(path, os.O_RDWR | os.O_CREAT, 0o600)
        try:
            if os.name == "nt":
                import msvcrt
                if os.fstat(descriptor).st_size == 0:
                    os.write(descriptor, b"\0")
                os.lseek(descriptor, 0, os.SEEK_SET)
                while True:
                    try:
                        msvcrt.locking(descriptor, msvcrt.LK_NBLCK, 1)
                        break
                    except OSError:
                        time.sleep(0.05)
            else:
                import fcntl
                fcntl.flock(descriptor, fcntl.LOCK_EX)
            yield
        finally:
            if os.name == "nt":
                import msvcrt
                os.lseek(descriptor, 0, os.SEEK_SET)
                msvcrt.locking(descriptor, msvcrt.LK_UNLCK, 1)
            else:
                import fcntl
                fcntl.flock(descriptor, fcntl.LOCK_UN)
            os.close(descriptor)


def sync_directory(path):
    if os.name != "nt":
        fd = os.open(path, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        try:
            os.fsync(fd)
        finally:
            os.close(fd)


def write_bytes(path, raw, *, immutable=False):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    if path.is_symlink():
        raise TargetError("OPERATOR_PATH", "A saved object cannot be a symbolic link.")
    if immutable and path.exists():
        if path.read_bytes() != raw:
            raise TargetError("IMMUTABLE_OBJECT_CHANGED", "The retained source object has different bytes.")
        return
    temp = path.parent / ("." + path.name + "." + uuid.uuid4().hex + ".tmp")
    fd = os.open(temp, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(raw)
            stream.flush()
            os.fsync(stream.fileno())
        if immutable:
            try:
                os.link(temp, path)
            except FileExistsError:
                if path.read_bytes() != raw:
                    raise TargetError("IMMUTABLE_OBJECT_CHANGED", "The retained source object has different bytes.")
            temp.unlink()
        else:
            os.replace(temp, path)
        sync_directory(path.parent)
    finally:
        try:
            temp.unlink()
        except FileNotFoundError:
            pass


class Store:
    def __init__(self, root):
        self.root = Path(root).resolve() / "operator"
        self.root.mkdir(parents=True, exist_ok=True, mode=0o700)
        for name in ("objects", "requests", "deployments", "uploads", "exports", "controls", "cohorts"):
            (self.root / name).mkdir(exist_ok=True, mode=0o700)

    def locked(self):
        return file_lock(self.root / "workspace.lock")

    def put_bytes(self, raw):
        identity = hashlib.sha256(raw).hexdigest()
        write_bytes(self.root / "objects" / identity, raw, immutable=True)
        return {"sha256": identity, "bytes": len(raw)}

    def read_bytes(self, identity):
        checked_id(identity)
        raw = (self.root / "objects" / identity).read_bytes()
        if hashlib.sha256(raw).hexdigest() != identity:
            raise TargetError("OBJECT_HASH", "A retained source object no longer matches its identity.")
        return raw

    def put(self, value):
        return self.put_bytes(canonical(value))

    def read(self, identity):
        return json.loads(self.read_bytes(identity).decode("utf-8"))

    def _index(self, collection, identity):
        if collection not in ("requests", "deployments", "cohorts"):
            raise TargetError("OPERATOR_COLLECTION", "Unknown operator collection.")
        return self.root / collection / (checked_id(identity) + ".json")

    def index(self, collection, identity):
        path = self._index(collection, identity)
        if not path.exists():
            raise TargetError("OPERATOR_NOT_FOUND", "The selected saved item does not exist.")
        raw = path.read_bytes()
        result = json.loads(raw.decode("utf-8"))
        if result.get("id") != identity:
            raise TargetError("INDEX_ID", "The saved index names another item.")
        return result

    def save(self, collection, value, *, expected_revision=None):
        identity = checked_id(value["id"])
        path = self._index(collection, identity)
        previous = json.loads(path.read_text(encoding="utf-8")) if path.exists() else None
        revision = previous.get("revision", 0) if previous else 0
        if expected_revision is not None and expected_revision != revision:
            raise TargetError("STALE_REVISION", "This item changed; reopen its current revision.")
        successor = dict(value)
        successor["revision"] = revision + 1
        successor["updated_at"] = utcnow()
        successor["snapshot_sha256"] = digest({k: v for k, v in successor.items() if k != "snapshot_sha256"})
        write_bytes(path, canonical(successor))
        return successor

    def list(self, collection, *, cursor="", limit=25):
        if collection not in ("requests", "deployments", "cohorts") or not 1 <= limit <= 100:
            raise TargetError("OPERATOR_PAGE", "Choose a page size from 1 to 100.")
        rows = []
        for path in (self.root / collection).glob("*.json"):
            value = json.loads(path.read_text(encoding="utf-8"))
            rows.append(value)
        rows.sort(key=lambda row: (row.get("created_at", ""), row["id"]), reverse=True)
        if cursor:
            positions = [i for i, row in enumerate(rows) if row["id"] == cursor]
            if len(positions) != 1:
                raise TargetError("OPERATOR_CURSOR", "Reopen the list; its selected cursor is absent.")
            rows = rows[positions[0] + 1:]
        page = rows[:limit]
        return {"items": page, "next_cursor": page[-1]["id"] if len(rows) > limit else "",
                "complete": len(rows) <= limit}

    def request(self, request_id, kind, arguments):
        checked_id(request_id)
        identity = digest({"kind": kind, "arguments": arguments})
        path = self._index("requests", request_id)
        if path.exists():
            previous = self.index("requests", request_id)
            if previous["input_sha256"] != identity:
                raise TargetError("REQUEST_REUSED", "This original request ID belongs to different input.")
            return previous
        result = {"schema": "portfolio.operator-request.v1", "id": request_id,
                  "kind": kind, "arguments": arguments, "input_sha256": identity,
                  "created_at": utcnow(), "state": "QUEUED"}
        return self.save("requests", result, expected_revision=0)

    def upload(self, raw, filename):
        with self.locked():
            return self._upload(raw, filename)

    def _upload(self, raw, filename):
        if not isinstance(filename, str) or not filename or len(filename) > 240 or any(x in filename for x in ("/", "\\", "\0")):
            raise TargetError("SOURCE_FILENAME", "Use the selected document's base filename.")
        object_ref = self.put_bytes(raw)
        directory = self.root / "uploads" / object_ref["sha256"]
        directory.mkdir(exist_ok=True, mode=0o700)
        path = directory / filename
        write_bytes(path, raw, immutable=True)
        return {"schema": "portfolio.operator-upload.v1", "sha256": object_ref["sha256"],
                "bytes": len(raw), "filename": filename, "path": str(path)}

    def selected_upload(self, value):
        if not isinstance(value, dict):
            raise TargetError("SOURCE_UPLOAD", "Select a retained uploaded source.")
        identity = checked_id(value.get("sha256"))
        name = value.get("filename")
        if not isinstance(name, str) or Path(name).name != name or "/" in name or "\\" in name:
            raise TargetError("SOURCE_FILENAME", "Invalid retained source filename.")
        path = self.root / "uploads" / identity / name
        before = path.stat()
        digestor, count = hashlib.sha256(), 0
        with open(path, "rb") as original:
            for chunk in iter(lambda: original.read(1024 * 1024), b""):
                digestor.update(chunk)
                count += len(chunk)
        after = path.stat()
        if digestor.hexdigest() != identity or ("bytes" in value and count != value["bytes"]) or (
                before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns) != (
                after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns):
            raise TargetError("SOURCE_UPLOAD_HASH", "The selected uploaded source changed.")
        return path

    def upload_stream(self, stream, length, filename):
        with self.locked():
            return self._upload_stream(stream, length, filename)

    def _upload_stream(self, stream, length, filename):
        if not isinstance(filename, str) or not filename or len(filename) > 240 or any(x in filename for x in ("/", "\\", "\0")):
            raise TargetError("SOURCE_FILENAME", "Use the selected document's base filename.")
        temp = self.root / "uploads" / ("." + uuid.uuid4().hex + ".incoming")
        digestor, count = hashlib.sha256(), 0
        try:
            with open(temp, "xb") as target:
                os.chmod(temp, 0o600)
                while count < length:
                    chunk = stream.read(min(1024 * 1024, length - count))
                    if not chunk:
                        raise TargetError("SOURCE_INCOMPLETE", "The selected document upload ended early.")
                    target.write(chunk)
                    digestor.update(chunk)
                    count += len(chunk)
                target.flush()
                os.fsync(target.fileno())
            identity = digestor.hexdigest()
            object_path = self.root / "objects" / identity
            try:
                os.link(temp, object_path)
            except FileExistsError:
                actual = hashlib.sha256()
                with open(object_path, "rb") as original:
                    for chunk in iter(lambda: original.read(1024 * 1024), b""):
                        actual.update(chunk)
                if actual.hexdigest() != identity:
                    raise TargetError("SOURCE_OBJECT_CHANGED", "The retained document object changed.")
            sync_directory(object_path.parent)
            directory = self.root / "uploads" / identity
            directory.mkdir(exist_ok=True, mode=0o700)
            path = directory / filename
            try:
                os.link(object_path, path)
            except FileExistsError:
                if path.stat().st_ino != object_path.stat().st_ino or path.stat().st_dev != object_path.stat().st_dev:
                    actual = hashlib.sha256()
                    with open(path, "rb") as original:
                        for chunk in iter(lambda: original.read(1024 * 1024), b""):
                            actual.update(chunk)
                    if actual.hexdigest() != identity:
                        raise TargetError("SOURCE_UPLOAD_CHANGED", "The selected source filename has different bytes.")
            sync_directory(directory)
            return {"schema": "portfolio.operator-upload.v1", "sha256": identity,
                    "bytes": count, "filename": filename, "path": str(path)}
        finally:
            try:
                temp.unlink()
            except FileNotFoundError:
                pass

    def control(self, deployment_id, request_id, *, pause):
        checked_id(deployment_id)
        checked_id(request_id)
        path = self.root / "controls" / (deployment_id + ".json")
        with file_lock(path.with_suffix(".lock")):
            value = {"schema": "portfolio.target-control.v1", "deployment_id": deployment_id,
                     "request_id": request_id, "pause": bool(pause), "at": utcnow()}
            write_bytes(path, canonical(value))
            return value

    def paused(self, deployment_id):
        path = self.root / "controls" / (checked_id(deployment_id) + ".json")
        return bool(json.loads(path.read_text(encoding="utf-8")).get("pause")) if path.exists() else False


    def retain_file(self, source, expected_sha256, expected_bytes):
        source = Path(source)
        before = source.stat()
        hash_value, count = hashlib.sha256(), 0
        with open(source, "rb") as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                hash_value.update(chunk)
                count += len(chunk)
        after = source.stat()
        if (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns) != (
                after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns) or (
                count != expected_bytes or hash_value.hexdigest() != expected_sha256):
            raise TargetError("NATIVE_EXPORT_CHANGED", "The original native export changed during receiving.")
        target = self.root / "objects" / checked_id(expected_sha256)
        try:
            os.link(source, target)
        except FileExistsError:
            digestor, retained_bytes = hashlib.sha256(), 0
            with open(target, "rb") as original:
                for chunk in iter(lambda: original.read(1024 * 1024), b""):
                    digestor.update(chunk)
                    retained_bytes += len(chunk)
            if digestor.hexdigest() != expected_sha256 or retained_bytes != expected_bytes:
                raise TargetError("NATIVE_EXPORT_CONFLICT", "The retained original export differs.")
        sync_directory(target.parent)
        return {"sha256": expected_sha256, "bytes": expected_bytes}

"""Original Project scheduling API transport and retained metadata contract.

Reference: MicrosoftDocs/dynamics-365-project-operations schedule-api-preview,
scheduling-apis-powerautomate and schedule-api-logs; see SOURCE_REFERENCES.json.
This module issues no automatic POST retries and never uses generic CRUD writes.
"""
from __future__ import annotations

import base64
import datetime as dt
import hashlib
import http.client
import json
import os
from pathlib import Path
import re
import ssl
import stat
from urllib.parse import quote, urlencode, urlsplit
import uuid
import xml.etree.ElementTree as ET

ACTIONS = {
    "msdyn_CreateProjectV1": ("Project",),
    "msdyn_CreateTeamMemberV1": ("TeamMember",),
    "msdyn_CreateOperationSetV1": ("ProjectId", "Description"),
    "msdyn_PssCreateV1": ("Entity", "OperationSetId"),
    "msdyn_PssUpdateV1": ("Entity", "OperationSetId"),
    "msdyn_PssDeleteV1": ("RecordId", "EntityLogicalName", "OperationSetId"),
    "msdyn_ExecuteOperationSetV1": ("OperationSetId",),
    "msdyn_AbandonOperationSetV1": ("OperationSetId",),
    "msdyn_PssUpdateResourceAssignmentContourV1": (
        "ResourceAssignmentId", "UpdatedContours", "OperationSetId"),
}
ENTITIES = (
    "systemuser", "msdyn_project", "msdyn_projectteam", "msdyn_projectbucket",
    "msdyn_projecttask", "msdyn_resourceassignment", "msdyn_projecttaskdependency",
    "msdyn_operationset", "msdyn_operationsetdetail", "msdyn_psserrorlog",
)
NS = {"edm": "http://docs.oasis-open.org/odata/ns/edm"}
SAFE_HEADERS = {
    "content-type", "content-length", "date", "etag", "retry-after",
    "request-id", "x-ms-request-id", "x-ms-service-request-id", "req_id",
    "x-ms-correlation-request-id", "activityid", "preference-applied",
}
NAME = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


class TargetError(RuntimeError):
    def __init__(self, code, message, *, evidence=None, dispatched=False):
        super().__init__(message)
        self.code, self.evidence, self.dispatched = code, evidence, dispatched


def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
                      allow_nan=False).encode("utf-8")


def digest(value):
    return hashlib.sha256(canonical(value)).hexdigest()


def utcnow():
    return dt.datetime.now(dt.timezone.utc).isoformat()


def guid(value):
    try:
        parsed = str(uuid.UUID(str(value)))
    except (ValueError, TypeError, AttributeError) as exc:
        raise TargetError("TARGET_GUID", "A complete native GUID is required.") from exc
    if parsed == str(uuid.UUID(int=0)):
        raise TargetError("TARGET_GUID", "A nonzero native GUID is required.")
    return parsed


def logical_name(value):
    if not isinstance(value, str) or not NAME.fullmatch(value):
        raise TargetError("TARGET_NAME", "Invalid native entity or field name.")
    return value


def odata_string(value):
    return "'" + str(value).replace("'", "''") + "'"


def public_profile(profile):
    return {key: profile[key] for key in (
        "id", "label", "kind", "api_origin", "api_version", "user_id",
        "organization_id", "source_timezone", "licensed_project_user",
        "status_semantics", "operation_set_size",
    ) if key in profile}


def read_profiles(path, workspace_root):
    """Read a locally selected private configuration; tokens stay outside archives."""
    profiles = {"mspdi": {"id": "mspdi", "label": "Microsoft Project XML",
                          "kind": "mspdi"}}
    if path is None:
        return profiles
    config_path = Path(path).expanduser().resolve(strict=True)
    root = Path(workspace_root).resolve()
    if config_path == root or root in config_path.parents:
        raise TargetError("PRIVATE_PROFILE_LOCATION",
                          "Keep the private target configuration outside this workspace.")
    raw = json.loads(config_path.read_text(encoding="utf-8"))
    if raw.get("schema") != "portfolio.target-profiles.v1" or not isinstance(raw.get("targets"), list):
        raise TargetError("TARGET_PROFILES", "Expected portfolio.target-profiles.v1.")
    for item in raw["targets"]:
        if not isinstance(item, dict) or item.get("kind") != "project_operations":
            raise TargetError("TARGET_PROFILE", "Use an explicit Project Operations target.")
        p = dict(item)
        key = p.get("id")
        if not isinstance(key, str) or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,79}", key) or key in profiles:
            raise TargetError("TARGET_PROFILE_ID", "Target IDs must be distinct.")
        u = urlsplit(p.get("api_origin", ""))
        if u.scheme != "https" or not u.hostname or u.username or u.password or u.query or u.fragment or u.path not in ("", "/"):
            raise TargetError("TARGET_ORIGIN", "Select one exact HTTPS Dynamics API origin.")
        p["api_origin"] = "https://" + u.netloc.lower()
        if p.get("api_version", "9.2") not in ("9.1", "9.2"):
            raise TargetError("TARGET_VERSION", "Select native API version 9.1 or 9.2.")
        p.setdefault("api_version", "9.2")
        p["user_id"], p["organization_id"] = guid(p.get("user_id")), guid(p.get("organization_id"))
        if p.get("licensed_project_user") is not True:
            raise TargetError("LICENSED_USER_SELECTION",
                              "Select the licensed Microsoft Project user for this target.")
        p["operation_set_size"] = int(p.get("operation_set_size", 200))
        if not 1 <= p["operation_set_size"] <= 200:
            raise TargetError("OPERATION_SET_LIMIT", "A native OperationSet holds at most 200 operations.")
        token_path = Path(p.get("token_file", "")).expanduser()
        if not token_path.is_absolute():
            token_path = config_path.parent / token_path
        token_path = token_path.resolve(strict=True)
        if token_path == root or root in token_path.parents:
            raise TargetError("PRIVATE_TOKEN_LOCATION", "Keep the bearer token outside the portable workspace.")
        p["token_file"] = str(token_path)
        p["timeout_seconds"] = int(p.get("timeout_seconds", 90))
        if not 5 <= p["timeout_seconds"] <= 600:
            raise TargetError("TARGET_TIMEOUT", "Choose a target timeout from 5 to 600 seconds.")
        p["max_response_bytes"] = int(p.get("max_response_bytes", 64 * 1024 * 1024))
        if not 1024 <= p["max_response_bytes"] <= 256 * 1024 * 1024:
            raise TargetError("TARGET_RESPONSE_LIMIT", "Choose a complete response limit up to 256 MiB.")
        profiles[key] = p
    return profiles


def access_token(profile):
    path = Path(profile["token_file"])
    before = path.stat()
    if not stat.S_ISREG(before.st_mode) or before.st_size > 1024 * 1024:
        raise TargetError("TOKEN_FILE", "The selected token file must be a small regular file.")
    if os.name == "posix" and before.st_mode & 0o077:
        raise TargetError("TOKEN_PERMISSIONS", "The selected token file must be private to its owner.")
    value = path.read_text(encoding="utf-8").strip()
    after = path.stat()
    if (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns) != (
            after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns):
        raise TargetError("TOKEN_CHANGED", "The selected token changed during this read.")
    if value.startswith("{"):
        value = json.loads(value).get("access_token")
    if not isinstance(value, str) or not value or any(c.isspace() for c in value) or len(value) > 65536:
        raise TargetError("TOKEN_VALUE", "Expected the selected delegated access token.")
    return value


class Metadata:
    """Exact selected CSDL projection; native entity sets and casing remain authoritative."""
    def __init__(self, xml_bytes):
        if b"<!DOCTYPE" in xml_bytes.upper() or b"<!ENTITY" in xml_bytes.upper():
            raise TargetError("METADATA_XML", "Unexpected external XML declaration.")
        try:
            document = ET.fromstring(xml_bytes)
        except ET.ParseError as exc:
            raise TargetError("METADATA_XML", "The native CSDL response is not complete XML.") from exc
        self.sha256 = hashlib.sha256(xml_bytes).hexdigest()
        types = {}
        for schema in document.findall(".//edm:Schema", NS):
            namespace = schema.get("Namespace", "")
            for node in schema.findall("edm:EntityType", NS):
                types[namespace + "." + node.get("Name", "")] = node
        sets = {}
        for node in document.findall(".//edm:EntitySet", NS):
            sets.setdefault(node.get("EntityType"), []).append(node.get("Name"))
        self.entities = {}
        def fields(type_name, seen=()):
            if type_name in seen or type_name not in types:
                raise TargetError("METADATA_TYPE", "Incomplete or circular native entity inheritance.")
            node = types[type_name]
            base = node.get("BaseType")
            result = fields(base, (*seen, type_name)) if base else {"properties": {}, "navigation": {}, "key": None}
            result = json.loads(json.dumps(result))
            for prop in node.findall("edm:Property", NS):
                result["properties"][prop.get("Name")] = dict(prop.attrib)
            for prop in node.findall("edm:NavigationProperty", NS):
                result["navigation"][prop.get("Name")] = {
                    **prop.attrib,
                    "constraints": [dict(x.attrib) for x in prop.findall("edm:ReferentialConstraint", NS)],
                }
            key = node.find("edm:Key/edm:PropertyRef", NS)
            if key is not None:
                result["key"] = key.get("Name")
            return result
        for name in ENTITIES:
            qualified = "Microsoft.Dynamics.CRM." + name
            if qualified not in types:
                continue
            choices = sets.get(qualified, [])
            if len(choices) != 1:
                raise TargetError("METADATA_ENTITY_SET", "Native entity set is ambiguous for " + name)
            self.entities[name] = {**fields(qualified), "set": choices[0], "type": qualified}
        self.actions = {}
        for node in document.findall(".//edm:Action", NS):
            name = node.get("Name")
            if name in ACTIONS and node.get("IsBound", "false").lower() != "true":
                if name in self.actions:
                    raise TargetError("METADATA_ACTION", "Ambiguous native action " + name)
                self.actions[name] = {p.get("Name"): dict(p.attrib) for p in node.findall("edm:Parameter", NS)}
        for action, parameters in ACTIONS.items():
            if action not in self.actions or set(self.actions[action]) != set(parameters):
                raise TargetError("TARGET_ACTION_UNAVAILABLE",
                                  "The selected environment does not expose the expected native " + action)
        for name in ENTITIES:
            if name not in self.entities:
                raise TargetError("TARGET_ENTITY_UNAVAILABLE", "The selected environment lacks " + name)

    def summary(self):
        return {"schema": "portfolio.native-target-metadata.v1", "sha256": self.sha256,
                "entities": self.entities, "actions": self.actions}

    def entity(self, name):
        try:
            return self.entities[name]
        except KeyError as exc:
            raise TargetError("TARGET_ENTITY", "Entity is outside the reviewed target contract.") from exc

    def field(self, entity, wanted, *, navigation=False):
        group = self.entity(entity)["navigation" if navigation else "properties"]
        candidates = [name for name in group if name.lower() == wanted.lower()]
        if len(candidates) != 1:
            raise TargetError("TARGET_FIELD", "Native field is absent or ambiguous: " + entity + "." + wanted)
        return candidates[0]

    def lookup(self, entity, navigation):
        name = self.field(entity, navigation, navigation=True)
        constraints = self.entity(entity)["navigation"][name]["constraints"]
        if len(constraints) != 1:
            raise TargetError("TARGET_LOOKUP", "Expected one native lookup constraint for " + entity + "." + name)
        return constraints[0]["Property"]

    def binding(self, entity, record_id):
        return "/" + self.entity(entity)["set"] + "(" + guid(record_id) + ")"

    def validate_entity(self, payload):
        if not isinstance(payload, dict) or not isinstance(payload.get("@odata.type"), str):
            raise TargetError("TARGET_ENTITY_PAYLOAD", "A native typed entity is required.")
        name = payload["@odata.type"].removeprefix("Microsoft.Dynamics.CRM.")
        schema = self.entity(name)
        for key, value in payload.items():
            if key == "@odata.type":
                continue
            if key.endswith("@odata.bind"):
                nav = key[:-11]
                if nav not in schema["navigation"]:
                    raise TargetError("TARGET_BINDING", "Unknown selected native relationship " + key)
                if not isinstance(value, str) or not re.fullmatch(r"/[A-Za-z_][A-Za-z0-9_]*\([0-9a-f-]{36}\)", value):
                    raise TargetError("TARGET_BINDING", "Expected a prepared native entity reference.")
                target = schema["navigation"][nav].get("Type", "").removeprefix("Microsoft.Dynamics.CRM.")
                if target in self.entities and value.split("(")[0] != "/" + self.entity(target)["set"]:
                    raise TargetError("TARGET_BINDING", "Relationship points to another entity set.")
            elif key not in schema["properties"]:
                raise TargetError("TARGET_PROPERTY", "Unknown selected native property " + name + "." + key)
        return name


class NativeTarget:
    def __init__(self, profile, *, observe=None):
        if profile.get("kind") != "project_operations":
            raise TargetError("TARGET_KIND", "Select the Project Operations target.")
        self.profile = profile
        self.origin = profile["api_origin"]
        self.api_root = self.origin + "/api/data/v" + profile["api_version"] + "/"
        self.observe = observe or (lambda value: None)
        self.metadata = None

    def request(self, method, relative, payload=None, *, allow_not_found=False, before_dispatch=None):
        """One actual HTTP attempt. The caller saves request identity before a POST."""
        if method not in ("GET", "POST"):
            raise TargetError("TARGET_METHOD", "Only native reads and scheduling actions are supported.")
        url = relative if relative.startswith("https://") else self.api_root + relative
        parsed = urlsplit(url)
        root = urlsplit(self.api_root)
        if (parsed.scheme, parsed.netloc) != (root.scheme, root.netloc) or not parsed.path.startswith(root.path) or parsed.fragment or parsed.username:
            raise TargetError("TARGET_URL", "The native URL must stay in the selected environment API.")
        if any(c in url for c in ("\r", "\n", "\x00")):
            raise TargetError("TARGET_URL", "Invalid target URL.")
        body = canonical(payload) if payload is not None else None
        token = access_token(self.profile)
        headers = {"Authorization": "Bearer " + token, "Accept": "application/json",
                   "OData-Version": "4.0", "OData-MaxVersion": "4.0",
                   "Accept-Encoding": "identity",
                   "Prefer": 'odata.include-annotations="OData.Community.Display.V1.FormattedValue"'}
        if method == "GET":
            headers["If-None-Match"] = "null"
        if body is not None:
            headers["Content-Type"] = "application/json; charset=utf-8"
        conn = http.client.HTTPSConnection(parsed.hostname, parsed.port or 443,
                                          timeout=self.profile.get("timeout_seconds", 90),
                                          context=ssl.create_default_context())
        started = utcnow()
        dispatched = False
        response = None
        raw = b""
        try:
            if before_dispatch is not None:
                before_dispatch()
            # Once request() begins, a lost reply may conceal an accepted native write.
            dispatched = True
            conn.request(method, parsed.path + (("?" + parsed.query) if parsed.query else ""),
                         body=body, headers=headers)
            res = conn.getresponse()
            limit = self.profile.get("max_response_bytes", 64 * 1024 * 1024)
            chunks, count = [], 0
            while True:
                chunk = res.read(min(1024 * 1024, limit + 1 - count))
                if not chunk:
                    break
                count += len(chunk)
                if count > limit:
                    raise TargetError("TARGET_RESPONSE_LIMIT",
                                      "The native response exceeds the selected complete-response limit.",
                                      dispatched=dispatched)
                chunks.append(chunk)
            raw = b"".join(chunks)
            response = {"method": method, "url": url, "started_at": started,
                        "finished_at": utcnow(), "status": res.status,
                        "headers": {k.lower(): v for k, v in res.getheaders() if k.lower() in SAFE_HEADERS},
                        "bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest(),
                        "body_base64": base64.b64encode(raw).decode("ascii"), "complete": True}
            self.observe(response)
            if allow_not_found and res.status == 404:
                return None, response
            if not 200 <= res.status < 300:
                raise TargetError("TARGET_HTTP_" + str(res.status),
                                  "The native service returned HTTP " + str(res.status) + ".",
                                  evidence=response, dispatched=dispatched)
            if relative == "$metadata":
                return raw, response
            if not raw:
                return {}, response
            try:
                data = json.loads(raw.decode("utf-8-sig"))
            except (UnicodeError, json.JSONDecodeError) as exc:
                raise TargetError("TARGET_JSON", "The native response is not complete JSON.",
                                  evidence=response, dispatched=dispatched) from exc
            return data, response
        except TargetError:
            raise
        except (OSError, http.client.HTTPException, ssl.SSLError) as exc:
            evidence = {"method": method, "url": url, "started_at": started, "finished_at": utcnow(),
                        "complete": False, "error_type": type(exc).__name__}
            self.observe(evidence)
            raise TargetError("TARGET_TRANSPORT", "The native connection ended before a complete response.",
                              evidence=evidence, dispatched=dispatched) from exc
        finally:
            conn.close()
            token = ""

    def get(self, relative, *, allow_not_found=False):
        return self.request("GET", relative, allow_not_found=allow_not_found)[0]

    def collection(self, relative, *, limit=250000):
        values, seen, pages = [], set(), []
        while relative:
            if relative in seen:
                raise TargetError("TARGET_PAGINATION", "The native collection repeated a page.")
            seen.add(relative)
            page, evidence = self.request("GET", relative)
            if not isinstance(page, dict) or not isinstance(page.get("value"), list):
                raise TargetError("TARGET_COLLECTION", "Expected a complete native collection page.")
            values.extend(page["value"])
            pages.append({"sha256": evidence["sha256"], "url": evidence["url"], "count": len(page["value"])})
            if len(values) > limit:
                raise TargetError("TARGET_COLLECTION_LIMIT", "The native collection exceeds the selected limit.")
            relative = page.get("@odata.nextLink")
            if relative is not None and not isinstance(relative, str):
                raise TargetError("TARGET_PAGINATION", "Invalid native continuation link.")
        return {"value": values, "pages": pages, "complete": True}

    def action(self, action, parameters, *, before_dispatch=None):
        if self.metadata is None or action not in ACTIONS or set(parameters) != set(ACTIONS[action]):
            raise TargetError("TARGET_ACTION", "Use the probed original scheduling action contract.")
        if action in ("msdyn_CreateProjectV1", "msdyn_CreateTeamMemberV1"):
            self.metadata.validate_entity(next(iter(parameters.values())))
        if "Entity" in parameters:
            self.metadata.validate_entity(parameters["Entity"])
        for key in ("OperationSetId", "ProjectId", "RecordId", "ResourceAssignmentId"):
            if key in parameters:
                guid(parameters[key])
        if action == "msdyn_PssUpdateResourceAssignmentContourV1":
            try:
                contours = json.loads(parameters["UpdatedContours"])
            except (TypeError, json.JSONDecodeError) as exc:
                raise TargetError("TARGET_CONTOURS", "Contours must use the native serialized JSON value.") from exc
            if not isinstance(contours, list) or len(contours) > 100:
                raise TargetError("TARGET_CONTOURS", "A native contour update accepts at most 100 slices.")
        return self.request("POST", action, parameters, before_dispatch=before_dispatch)[0]

    def probe(self):
        identity = self.get("WhoAmI")
        if guid(identity.get("UserId")) != self.profile["user_id"] or guid(identity.get("OrganizationId")) != self.profile["organization_id"]:
            raise TargetError("TARGET_IDENTITY", "The delegated user or organization differs from the selected target.")
        xml, xml_receipt = self.request("GET", "$metadata")
        self.metadata = Metadata(xml)
        m = self.metadata
        user = self.record("systemuser", self.profile["user_id"])
        disabled = m.field("systemuser", "isdisabled")
        app = m.field("systemuser", "applicationid")
        if not user or user.get(disabled) is not False or user.get(app):
            raise TargetError("TARGET_USER_KIND", "Scheduling requires the selected active delegated Project user.")
        status_field = m.field("msdyn_operationset", "msdyn_status")
        choices = self.get("EntityDefinitions(LogicalName='msdyn_operationset')/Attributes(LogicalName='" +
                           status_field + "')/Microsoft.Dynamics.CRM.PicklistAttributeMetadata?$select=LogicalName&$expand=OptionSet")
        options = choices.get("OptionSet", {}).get("Options")
        if not isinstance(options, list) or not options:
            raise TargetError("TARGET_STATUS_METADATA", "Native OperationSet status choices are required.")
        selected = self.profile.get("status_semantics", {})
        semantics = {}
        for role in ("completed", "failed", "abandoned"):
            explicit = selected.get(role)
            if explicit is not None:
                candidates = [o for o in options if o.get("Value") == explicit]
            else:
                candidates = []
                for option in options:
                    labels = option.get("Label", {}).get("LocalizedLabels", [])
                    if any(str(label.get("Label", "")).strip().casefold() == role for label in labels):
                        candidates.append(option)
            if len(candidates) == 1:
                semantics[role] = candidates[0]["Value"]
        if "completed" not in semantics or len(set(semantics.values())) != len(semantics):
            raise TargetError("TARGET_STATUS_SELECTION",
                              "Select the actual completed status from the returned native choices.",
                              evidence={"choices": options, "selected": selected})
        actor = {key: user.get(m.field("systemuser", key)) for key in
                 ("systemuserid", "isdisabled", "applicationid", "azureactivedirectoryobjectid")}
        link_field = m.field("msdyn_projecttaskdependency", "msdyn_linktype")
        link_choices = self.get("EntityDefinitions(LogicalName='msdyn_projecttaskdependency')/Attributes(LogicalName='" +
            link_field + "')/Microsoft.Dynamics.CRM.PicklistAttributeMetadata?$select=LogicalName&$expand=OptionSet")
        link_options = link_choices.get("OptionSet", {}).get("Options")
        if not isinstance(link_options, list) or not link_options:
            raise TargetError("TARGET_LINK_METADATA", "The actual dependency link-type choices are required.")
        result = {"schema": "portfolio.target-probe.v1", "captured_at": utcnow(),
                  "profile": public_profile(self.profile), "identity": identity,
                  "user": actor, "metadata": m.summary(), "metadata_response_sha256": xml_receipt["sha256"],
                  "status_choices": options, "status_semantics": semantics, "link_type_choices": link_options}
        result["sha256"] = digest(result)
        return result

    def record(self, entity, record_id):
        if self.metadata is None:
            raise TargetError("TARGET_METADATA_REQUIRED", "Probe the selected native target first.")
        return self.get(self.metadata.entity(entity)["set"] + "(" + guid(record_id) + ")",
                        allow_not_found=True)

    def operation_sets(self, project_id, *, description=None):
        m = self.metadata
        field = m.lookup("msdyn_operationset", "msdyn_project")
        expression = field + " eq " + guid(project_id)
        if description is not None:
            expression += " and " + m.field("msdyn_operationset", "msdyn_description") + " eq " + odata_string(description)
        return self.collection(m.entity("msdyn_operationset")["set"] + "?" +
                               urlencode({"$filter": expression}))

    def operation_details(self, operation_set_id):
        m = self.metadata
        return self.collection(m.entity("msdyn_operationsetdetail")["set"] + "?" + urlencode({
            "$filter": m.lookup("msdyn_operationsetdetail", "msdyn_operationset") + " eq " + guid(operation_set_id),
            "$orderby": m.field("msdyn_operationsetdetail", "msdyn_requestnumber") + " asc",
        }))

    def project_errors(self, project_id):
        m = self.metadata
        return self.collection(m.entity("msdyn_psserrorlog")["set"] + "?" + urlencode({
            "$filter": m.lookup("msdyn_psserrorlog", "msdyn_project") + " eq " + guid(project_id),
        }))


def operation_response(value, expected_set, expected_record=None):
    """Decode the provider's documented serialized OperationSetResponse field."""
    raw = value.get("OperationSetResponse") if isinstance(value, dict) else None
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except json.JSONDecodeError as exc:
            raise TargetError("OPERATION_RESPONSE", "Incomplete native OperationSetResponse.") from exc
    if not isinstance(raw, dict):
        raise TargetError("OPERATION_RESPONSE", "The native response omitted OperationSetResponse.")
    if guid(raw.get("operationSetId")) != guid(expected_set):
        raise TargetError("OPERATION_RESPONSE_ID", "The response names another native OperationSet.")
    if expected_record is not None and guid(raw.get("recordId")) != guid(expected_record):
        raise TargetError("OPERATION_RESPONSE_RECORD", "The response names another native record.")
    guid(raw.get("operationSetDetailId"))
    return raw

