/* Keep full native comparisons readable in the original receiving view. */
.card,header,.activity-strip{overflow-wrap:anywhere}
.panel,.table-scroll{min-width:0;max-width:100%}
.card button,.section-heading select{max-width:100%}
.comparison-scroll{max-height:42rem;overflow:auto;overscroll-behavior:contain}
.comparison-scroll:focus-visible{outline:2px solid #222;outline-offset:3px}
.comparison-scroll thead th{position:sticky;top:0;z-index:1}
#comparison-table,#definition-table{min-width:760px;table-layout:fixed}
#comparison-table th:nth-child(1),#definition-table th:nth-child(1){width:128px}
#comparison-table th:nth-child(2),#definition-table th:nth-child(2){width:192px}
#comparison-table th:nth-child(3),#definition-table th:nth-child(3){width:92px;white-space:nowrap}
#comparison-table td:nth-child(3),#definition-table td:nth-child(3){white-space:nowrap;overflow-wrap:normal}
#definition-sources>table{min-width:720px;table-layout:fixed}
#definition-sources th:first-child{width:128px}
@media(max-width:850px){.comparison-scroll{max-height:30rem}}

/* Retain every native reporting row inside a readable, scrollable region. */
